body:
Thanks Domenic. I confirmed that you've fixed many issues of `pipeTo` in #129. But maybe still some issues are left unaddressed. For example, if `pipeTo` is invoked when `ws` is in `waiting` state and then `rs` is cancelled, current `pipeTo` doesn't catch the event. I remember we had discussed several unusual use of `cancel()`. This might be categorized as such an unusual use case but not sure, sorry.

Anyway, I also tried writing working but simplified `pipeTo` implementation by select-ing on `rs` and `ws` using `Promise.race()` and using new functions you just introduced. Please take a quick look (I haven't tested it. I'll do it tomorrow).

```
function doPipe() {
  for (;;) {
    var ds = dest.state;
    if (ds === 'writable') {
      if (source.state === 'readable') {
        dest.write(source.read())
            .catch(cancelSource);
        continue;
      } else if (source.state === 'waiting') {
        Promise.race([source.wait(), dest.closed])
            .then(doPipe, doPipe);
      } else if (source.state === 'errored') {
        source.wait().catch(abortDest);
      } else if (source.state === 'closed') {
        closeDest();
      }
    } else if (ds === 'waiting') {
      if (source.state === 'readable') {
        Promise.race([source.closed, dest.wait()])
            .then(doPipe, doPipe);
      } else if (source.state === 'waiting') {
        Promise.race([source.wait(), dest.wait()])
            .then(doPipe, doPipe);
      } else if (source.state === 'errored') {
        source.wait().catch(abortDest);
      } else if (source.state === 'closed') {
        closeDest();
      }
    } else if (ds === 'errored' &&
               (source.state === 'readable' ||
                source.state === 'waiting')) {
      dest.wait().catch(cancelSource);
    } else if ((ds === 'closing' ||
                ds === 'closed') &&
               (source.state === 'readable' ||
                source.state === 'waiting')) {
      cancelSource(new TypeError(...));
    }
    return;
  }
}
```
